source = inputs.get('source') or 'darkweb'
pipeline = dict(inputs.get('pipeline') or {})
query = pipeline.get('query') or inputs.get('query') or ''
keyword_result = inputs.get('keyword_result') or {}
keyword_text = inputs.get('keyword_text') or ''
include_sources = set(pipeline.get('include_sources') or ['darkweb', 'telegram', 'web'])
enabled = source in include_sources




def add_keyword(rows, text, *, priority='medium', source_hint='', search_intent=''):
    text = str(text or '').strip()
    if not text:
        return
    key = text.lower()
    if key in seen:
        return
    seen.add(key)
    rows.append({
        'keyword': text,
        'priority': priority,
        'source_hint': source_hint,
        'search_intent': search_intent,
    })


seen = set()
rows = []
add_keyword(rows, query, priority='critical', source_hint='query', search_intent='all')

keywords = keyword_result.get('keywords') if isinstance(keyword_result, dict) else []
if isinstance(keywords, list):
    for entry in keywords:
        if isinstance(entry, dict):
            priority = entry.get('priority') or 'medium'
            search_intent = entry.get('search_intent') or 'all'
            if search_intent not in ('all', source):
                continue
            add_keyword(rows, entry.get('canonical'), priority=priority, source_hint='canonical', search_intent=search_intent)
            languages = entry.get('languages') or {}
            if isinstance(languages, dict):
                for lang, lang_values in languages.items():
                    if isinstance(lang_values, list):
                        for value in lang_values:
                            add_keyword(rows, value, priority=priority, source_hint='language:' + str(lang), search_intent=search_intent)
                    else:
                        add_keyword(rows, lang_values, priority=priority, source_hint='language:' + str(lang), search_intent=search_intent)
            aliases = entry.get('aliases') or entry.get('variants') or []
            if isinstance(aliases, list):
                for value in aliases:
                    add_keyword(rows, value, priority=priority, source_hint='alias', search_intent=search_intent)
        else:
            add_keyword(rows, entry, priority='medium', source_hint='keyword_list', search_intent='all')

MAX_KEYWORDS = 30
_priority_rank = {'critical': 0, 'high': 1, 'medium': 2, 'low': 3}
if enabled and len(rows) > MAX_KEYWORDS:
    indexed = list(enumerate(rows))
    indexed.sort(key=lambda x: (_priority_rank.get((x[1].get('priority') or 'medium'), 99), x[0]))
    rows = [r for _, r in indexed[:MAX_KEYWORDS]]

source_keywords = rows if enabled else []

outputs['source'] = source
outputs['source_enabled'] = enabled
outputs['query'] = query
outputs['pipeline'] = pipeline
outputs['keyword_result'] = keyword_result
outputs['keyword_text'] = keyword_text
outputs['source_keywords'] = source_keywords
outputs['searched_keywords'] = [row['keyword'] for row in source_keywords]
outputs['source_parallel_limit'] = 1
outputs['source_agent_type'] = 'darkweb-search-agent'
outputs['source_command'] = 'threat-intel-darkweb-batch-search'
outputs['source_description'] = 'Search dark web threat intelligence for a keyword batch'

from datetime import datetime, timezone, timedelta
import re

source = inputs.get('source') or 'darkweb'
query = inputs.get('query') or ''
pipeline = dict(inputs.get('pipeline') or {})
source_enabled = bool(inputs.get('source_enabled'))
keyword_rows = inputs.get('source_keywords') or []
source_result = inputs.get('source_agent_result') or {}

searched_keywords = []
for row in keyword_rows:
    if isinstance(row, dict):
        keyword = row.get('keyword') or row.get('term') or row.get('query')
    else:
        keyword = row
    keyword = str(keyword or '').strip()
    if keyword and keyword not in searched_keywords:
        searched_keywords.append(keyword)

if isinstance(source_result, dict):
    result_keywords = source_result.get('searched_keywords') or []
    if isinstance(result_keywords, list):
        for keyword in result_keywords:
            keyword = str(keyword or '').strip()
            if keyword and keyword not in searched_keywords:
                searched_keywords.append(keyword)

results = []
errors = []
notes = []
filtered_out = []


def append_error(value):
    if value is None:
        return
    if isinstance(value, list):
        for item in value:
            append_error(item)
        return
    text = str(value).strip()
    if text:
        errors.append(text)


def append_note(value):
    if value is None:
        return
    if isinstance(value, list):
        for item in value:
            append_note(item)
        return
    text = str(value).strip()
    if text:
        notes.append(text)


def normalize_result(item):
    if isinstance(item, dict):
        row = dict(item)
    else:
        row = {'value': item}
    row.setdefault('source', source)
    return row


def parse_result_date(value, fallback_text=''):
    # Try the explicit time field first (highest authority).
    text = str(value or '').strip()
    if text:
        m = re.search(r'(20\d{2})[-/\.年](\d{1,2})(?:[-/\.月](\d{1,2}))?', text)
        if m:
            try:
                return datetime(int(m.group(1)), int(m.group(2)), int(m.group(3) or '1'), tzinfo=timezone.utc).date()
            except Exception:
                pass
        m = re.search(r'\b(20\d{2})\b', text)
        if m:
            try:
                return datetime(int(m.group(1)), 12, 31, tzinfo=timezone.utc).date()
            except Exception:
                pass
    # Fall back to scanning summary/evidence/title text. Take the LATEST date found,
    # since publish/incident dates are usually the most recent date in the body.
    fb = str(fallback_text or '').strip()
    if not fb:
        return None
    candidates = []
    for m in re.finditer(r'(20\d{2})[-/\.年](\d{1,2})(?:[-/\.月](\d{1,2}))?', fb):
        try:
            candidates.append(datetime(int(m.group(1)), int(m.group(2)), int(m.group(3) or '1'), tzinfo=timezone.utc).date())
        except Exception:
            pass
    if not candidates:
        for m in re.finditer(r'(?<!\d)(20\d{2})(?!\d)', fb):
            try:
                candidates.append(datetime(int(m.group(1)), 12, 31, tzinfo=timezone.utc).date())
            except Exception:
                pass
    return max(candidates) if candidates else None


def result_time(item):
    if not isinstance(item, dict):
        return ''
    raw = item.get('raw') if isinstance(item.get('raw'), dict) else {}
    for key in ('time', 'date', 'published', 'publication_date', 'updatedTime', 'created_at'):
        if item.get(key):
            return item.get(key)
        if raw.get(key):
            return raw.get(key)
    return ''


def inside_time_window(item):
    window = pipeline.get('search_window_days')
    try:
        window = int(window)
    except Exception:
        return True
    if window <= 0:
        return True
    fb_parts = []
    if isinstance(item, dict):
        for k in ('summary', 'evidence', 'title'):
            v = item.get(k)
            if v:
                fb_parts.append(str(v))
        raw = item.get('raw')
        if isinstance(raw, dict):
            for k in ('summary', 'text', 'description', 'title'):
                v = raw.get(k)
                if v:
                    fb_parts.append(str(v))
    dt = parse_result_date(result_time(item), fallback_text=' '.join(fb_parts))
    if dt is None:
        return False  # 修法2: no parseable date in time field or fallback text -> drop
    cutoff = datetime.now(timezone.utc).date() - timedelta(days=max(window, 0))
    return dt >= cutoff


if isinstance(source_result, dict):
    append_error(source_result.get('errors'))
    append_note(source_result.get('notes'))
    raw_results = source_result.get('results') or []
    if isinstance(raw_results, list):
        for result in raw_results:
            row = normalize_result(result)
            if inside_time_window(row):
                results.append(row)
            else:
                filtered_out.append({
                    'title': row.get('title') or '',
                    'url': row.get('url') or '',
                    'time': result_time(row),
                    'reason': 'outside search_window_days=' + str(pipeline.get('search_window_days')),
                })
    elif raw_results:
        row = normalize_result(raw_results)
        if inside_time_window(row):
            results.append(row)
        else:
            filtered_out.append({
                'title': row.get('title') or '',
                'url': row.get('url') or '',
                'time': result_time(row),
                'reason': 'outside search_window_days=' + str(pipeline.get('search_window_days')),
            })
    raw_status = source_result.get('status') or 'completed'
else:
    raw_status = 'failed'
    append_error('source agent did not return structured output')

if filtered_out:
    notes.append('Filtered out %d %s results outside search_window_days=%s' % (len(filtered_out), source, pipeline.get('search_window_days')))

keyword_total = len(keyword_rows) or len(searched_keywords)

if not source_enabled:
    status = 'not_provided'
    if 'source excluded' not in notes:
        notes.append('source excluded')
elif keyword_total == 0:
    status = 'no_results'
elif raw_status in ('failed', 'timeout'):
    status = raw_status
elif raw_status == 'partial' and not results:
    status = 'partial'
elif raw_status == 'partial':
    status = 'partial'
elif not results:
    status = 'no_results'
else:
    status = 'completed'

metrics = {
    'keyword_total': keyword_total,
    'keyword_completed': len(searched_keywords) if status != 'failed' else 0,
    'keyword_failed': 0 if status != 'failed' else keyword_total,
    'elapsed_ms': 0,
    'max_parallel': inputs.get('source_parallel_limit'),
    'dispatch_mode': 'subagent_dedicated_python_batch',
    'filtered_out_of_window': len(filtered_out),
}

outputs['source'] = source
outputs['status'] = status
outputs['query'] = query
outputs['searched_keywords'] = searched_keywords
outputs['results'] = results
outputs['errors'] = errors
outputs['metrics'] = metrics
outputs['source_coverage'] = {source: status}
outputs['notes'] = notes
outputs['filtered_out'] = filtered_out
